/** Test-only line/paragraph control model of the displayed COBOL, independent of producer. */
export function cobolCandidate(owned:{no:string;dates:number[]}[],passes:{no:string;qualification:number;date:number}[],choice=[2,3,1,3,3]){const db=new Map(owned.map(r=>[r.no,structuredClone(r)])),sorted=structuredClone(passes).sort((a,b)=>a.no.localeCompare(b.no)),awards:string[]=[],[a,b,c,d,e]=choice;let current:{no:string;dates:number[]}|undefined,cr='',last:typeof passes[number]|undefined;const award=()=>{if(!current)throw Error('NO_RECORD');let cnt=1;while(cnt<=4&&current.dates[cnt-1]!==0)cnt++;let yes;if(e===0){const k=Number(cr);if(k<1||k>4)throw Error('SUBSCRIPT');yes=current.dates[k-1]===0;}else if(e===1){if(cnt>4)throw Error('SUBSCRIPT');yes=current.dates[cnt-1]===0;}else if(e===2)yes=current.dates.some(n=>n!==0);else yes=cnt>4;if(yes)awards.push(current.no);};const rewrite=()=>{if(!current)throw Error('NO_RECORD');db.set(current.no,structuredClone(current));};const write=()=>{if(cr!==''){if(d===3)award();rewrite();}};const upd=(r:typeof passes[number])=>{const changed=b===0?cr==='':b===1?r.no===cr:b===2?r.no==='':r.no!==cr;if(changed){write();current=structuredClone(db.get(r.no));if(!current)throw Error('NO_EMPLOYEE');cr=current.no;if(d===2)award();}if(!current)throw Error('UNREAD_RECORD');const k=r.qualification-1;if(c===0){if(k+1>=4)throw Error('SUBSCRIPT');current.dates[k+1]=current.dates[k];}else current.dates[k]=c===1?r.date:c===2?Number(r.no):0;};for(const r of sorted){last=r;upd(r);if(d===1)award();}if(d===0)award();if(a===0)cr='';else if(a===1){if(!last)throw Error('EOF_STALE');upd(last);}else if(a===2)write();else rewrite();if(d===1)award();return{records:[...db.values()].sort((a,b)=>a.no.localeCompare(b.no)),awards};}
